package org.cgse.core;
import java.math.*;import java.util.*;
public class SoftLearningCompare {
 static final BigInteger Z=BigInteger.ZERO,O=BigInteger.ONE;
 public static void main(String[]args){for(int pairs:new int[]{1,4,8,12,16,24})for(int extra:new int[]{0,8}){int n=pairs*2;var hard=new ArrayList<ExactLinearProgram.Constraint>();var soft=new ArrayList<CountSoftSearch.Soft>();for(int j=0;j<pairs;j++)hard.add(new ExactLinearProgram.Constraint(Map.of(j*2,O,j*2+1,O),O));for(int j=0;j<n;j++)soft.add(new CountSoftSearch.Soft(new ExactLinearProgram.Constraint(Map.of(j,O.negate()),O.negate()),O.shiftLeft(100)));for(int j=0;j<extra;j++)soft.add(new CountSoftSearch.Soft(new ExactLinearProgram.Constraint(Map.of(j%n,O),O),O));var low=new BigInteger[n];var high=new BigInteger[n];Arrays.fill(low,Z);Arrays.fill(high,O);var b=new PlanningBudget(0,20000000,256L<<20,()->false,System::nanoTime);long start=System.nanoTime();try(var p=new CountCoreSoft(hard,low,high,soft,b,65536)){while(!p.step()){}System.out.println("CASE pairs="+pairs+" irrelevant="+extra+" optimal="+p.optimal()+" witness="+(p.counts()!=null)+" lower="+p.lowerBound()+" cost="+p.cost()+" work="+b.nodes()+" ms="+((System.nanoTime()-start)/1e6));if(p.counts()!=null&&(p.optimal()&&!p.cost().equals(O.shiftLeft(100).multiply(BigInteger.valueOf(pairs)))||!OptimizationOracle.valid(hard,p.counts())))throw new AssertionError("wrong soft result");System.out.println("TRACE "+b.diagnostics());}if(b.reservedBytes()!=0)throw new AssertionError("compare leak");}}
}
